def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('native_facts')
    boundaries = view.get('source_boundaries')
    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['source_native_channel_unread'])
    arities = kernel.get('fact_arities') if type(kernel) is dict else None
    if type(arities) is not dict:
        return part(facts, negatives, witnesses, False, reasons + ['kernel_native_signatures_unread'])
    givens = ('s151_b', 's151_b_applies', 's151_c_applies', 's152_c_1', 's63_f_1_A', 's63_f_1_B')
    targets = query_names(kernel)
    seen = set()
    for record in records:
        if not support(witnesses, record, public, True):
            complete = False
            continue
        name = record.get('predicate')
        arguments = record.get('arguments')
        polarity = record.get('polarity')
        if type(name) is not str or type(arguments) is not list or polarity not in ('positive', 'negative'):
            complete = False
            continue
        if name in targets:
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        expected = arities.get(name)
        if type(expected) is not int or len(arguments) != expected:
            complete = False
            continue
        valid = True
        if name in givens:
            valid = valid_given(name, arguments)
        elif polarity == 'negative':
            valid = False
        elif name == 'amount_':
            valid = len(arguments) == 2 and type(arguments[0]) is str and type(arguments[1]) in (int, float)
        else:
            for argument in arguments:
                if type(argument) is not str:
                    valid = False
        if not valid:
            complete = False
            continue
        key = (name, tuple(arguments), polarity)
        if key in seen:
            continue
        seen.add(key)
        row = {'predicate': name, 'arguments': list(arguments)}
        add(negatives if polarity == 'negative' else facts, row)
    for boundary in boundaries:
        if not support(witnesses, boundary, public, True):
            complete = False
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)
